#include "stdafx.h"#include "Translator.h"namespace ns_HcdTranslator{  struct SFuncNumb   {    LPCSTR pName;    int ID;  };  static SFuncNumb sFuncs[] =   {    {"Math.TestBit", efMath_TestBit},    {"sqrt", efSQRT},    {"pow", efPOW},    {"atan", efATAN},    {"sin", efSIN},  };  int KHcdTranslator::IsFunc( LPCSTR pszName )  {    for( int i=0; i<_countof(sFuncs); i++ )    {      if( !_strcmpi(pszName,sFuncs[i].pName) )        return sFuncs[i].ID;    }    return -1;  }}